import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matvec_kernel(const float* A, const float* B, float* C, int M, int K) {
    extern __shared__ float sdata[];
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int stride = blockDim.x;

    float sum = 0.0f;
    for (int i = tid; i < K; i += stride) {
        sum += A[row*K + i] * B[i];
    }

    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        C[row] = sdata[0];
    }
}

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto out = torch::zeros({M}, A.options());

    const int block_size = 256;
    dim3 grid(M);
    dim3 block(block_size);
    size_t shared_mem = block_size * sizeof(float);

    matvec_kernel<<<grid, block, shared_mem>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        out.data_ptr<float>(),
        M,
        K
    );

    return out.view({-1, 1});  // Reshape to match original output dimensions
}
"""

matvec_cpp_source = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"

matvec = load_inline(
    name='matvec',
    cpp_sources=matvec_cpp_source,
    cuda_sources=matvec_cuda_source,
    functions=['matvec_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matvec.matvec_cuda(A, B)
